import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CU_ytobU.js";var i=JSON.parse(`{"title":"Class: BatchCodec","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: BatchCodec"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/protocol/classes/BatchCodec"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/protocol/classes/BatchCodec"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/protocol/src"}},"headers":[],"relativePath":"api/@jsprismarine/protocol/classes/BatchCodec.md","filePath":"api/@jsprismarine/protocol/classes/BatchCodec.md","lastUpdated":1794042973000}`),a={name:`api/@jsprismarine/protocol/classes/BatchCodec.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/protocol</a> / BatchCodec</p><h1 id="class-batchcodec" tabindex="-1">Class: BatchCodec <a class="header-anchor" href="#class-batchcodec" aria-label="Permalink to “Class: BatchCodec”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L33" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:33</a></p><p>A batch: the outermost Minecraft layer, sitting directly inside a RakNet frame.</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0xFE │ [algorithm byte] │ ⟨varint len, packet⟩ ⟨varint len, packet⟩ …</span></span></code></pre></div><p>The algorithm byte is present if and only if compression has been <em>negotiated</em> - which is not the same as this batch being compressed, and conflating the two is the trap here. A connection sends <code>RequestNetworkSettings</code> and receives <code>NetworkSettings</code> with no prefix at all; from the packet after that one, every batch carries a prefix, and a peer is free to make it <a href="./../#uncompressed-batch">UNCOMPRESSED_BATCH</a> whenever compressing would not pay. So the two states are two codecs - <a href="#uncompressed">BatchCodec.uncompressed</a> and <a href="#compressed">BatchCodec.compressed</a> - and a connection replaces one with the other exactly once.</p><p>Nothing here knows what a packet <em>is</em>: a batch is a list of opaque buffers. That is what lets a proxy route on ids it has no definition for, and what keeps this usable from both sides of a connection.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="decode" tabindex="-1">decode() <a class="header-anchor" href="#decode" aria-label="Permalink to “decode()”">​</a></h3><blockquote><p><strong>decode</strong>(<code>batch</code>): <code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L121" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:121</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="batch" tabindex="-1">batch <a class="header-anchor" href="#batch" aria-label="Permalink to “batch”">​</a></h5><p><code>Buffer</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p><hr><h3 id="decodeasync" tabindex="-1">decodeAsync() <a class="header-anchor" href="#decodeasync" aria-label="Permalink to “decodeAsync()”">​</a></h3><blockquote><p><strong>decodeAsync</strong>(<code>batch</code>): <code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L128" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:128</a></p><p>The async entry point; small compressed bodies inflate inline, and larger ones use zlib&#39;s async API.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="batch-1" tabindex="-1">batch <a class="header-anchor" href="#batch-1" aria-label="Permalink to “batch”">​</a></h5><p><code>Buffer</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]&gt;</p><hr><h3 id="encode" tabindex="-1">encode() <a class="header-anchor" href="#encode" aria-label="Permalink to “encode()”">​</a></h3><blockquote><p><strong>encode</strong>(<code>packets</code>): <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L54" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:54</a></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packets" tabindex="-1">packets <a class="header-anchor" href="#packets" aria-label="Permalink to “packets”">​</a></h5><p>readonly <code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code></p><hr><h3 id="encodeasync" tabindex="-1">encodeAsync() <a class="header-anchor" href="#encodeasync" aria-label="Permalink to “encodeAsync()”">​</a></h3><blockquote><p><strong>encodeAsync</strong>(<code>packets</code>): <code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L65" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:65</a></p><p>The same, with the deflate handed to zlib&#39;s asynchronous API.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packets-1" tabindex="-1">packets <a class="header-anchor" href="#packets-1" aria-label="Permalink to “packets”">​</a></h5><p>readonly <code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;&gt;</p><hr><h3 id="encodefullflushfragment" tabindex="-1">encodeFullFlushFragment() <a class="header-anchor" href="#encodefullflushfragment" aria-label="Permalink to “encodeFullFlushFragment()”">​</a></h3><blockquote><p><strong>encodeFullFlushFragment</strong>(<code>packet</code>): <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L80" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:80</a></p><p>Encodes one packet&#39;s length and bytes as an independently reusable raw-deflate fragment.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet" tabindex="-1">packet <a class="header-anchor" href="#packet" aria-label="Permalink to “packet”">​</a></h5><p><code>Buffer</code></p><p>One already encoded packet.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code></p><p>The non-final raw-deflate fragment for that packet.</p><hr><h3 id="encodefullflushfragmentasync" tabindex="-1">encodeFullFlushFragmentAsync() <a class="header-anchor" href="#encodefullflushfragmentasync" aria-label="Permalink to “encodeFullFlushFragmentAsync()”">​</a></h3><blockquote><p><strong>encodeFullFlushFragmentAsync</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L91" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:91</a></p><p>Encodes one packet fragment using zlib&#39;s asynchronous API.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet-1" tabindex="-1">packet <a class="header-anchor" href="#packet-1" aria-label="Permalink to “packet”">​</a></h5><p><code>Buffer</code></p><p>One already encoded packet.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;&gt;</p><p>The non-final raw-deflate fragment for that packet.</p><hr><h3 id="encodefullflushfragments" tabindex="-1">encodeFullFlushFragments() <a class="header-anchor" href="#encodefullflushfragments" aria-label="Permalink to “encodeFullFlushFragments()”">​</a></h3><blockquote><p><strong>encodeFullFlushFragments</strong>(<code>packets</code>, <code>fragments</code>): <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L106" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:106</a></p><p>Assembles a normal Bedrock batch from cached full-flush fragments.</p><p>The final empty block is the only final marker in the stream. Each fragment ended with <code>Z_FULL_FLUSH</code>, so it has no back-reference into another packet and can be shared safely.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packets-2" tabindex="-1">packets <a class="header-anchor" href="#packets-2" aria-label="Permalink to “packets”">​</a></h5><p>readonly <code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p><p>The decoded packet bytes in the order the client must receive them.</p><h5 id="fragments" tabindex="-1">fragments <a class="header-anchor" href="#fragments" aria-label="Permalink to “fragments”">​</a></h5><p>readonly <code>Buffer</code>&lt;<code>ArrayBufferLike</code>&gt;[]</p><p>One cached <code>encodeFullFlushFragment</code> result per packet.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code></p><p>A compressed Bedrock batch carrying the concatenated packet stream.</p><hr><h3 id="iscompressionenabled" tabindex="-1">isCompressionEnabled() <a class="header-anchor" href="#iscompressionenabled" aria-label="Permalink to “isCompressionEnabled()”">​</a></h3><blockquote><p><strong>isCompressionEnabled</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L50" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:50</a></p><p>Whether compression has been negotiated, i.e. whether batches carry a prefix byte.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="compressed" tabindex="-1">compressed() <a class="header-anchor" href="#compressed" aria-label="Permalink to “compressed()”">​</a></h3><blockquote><p><code>static</code> <strong>compressed</strong>(<code>settings</code>): <code>BatchCodec</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L45" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:45</a></p><p>The post-negotiation form: every batch carries an algorithm byte.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="settings" tabindex="-1">settings <a class="header-anchor" href="#settings" aria-label="Permalink to “settings”">​</a></h5><p><a href="./../#compressionsettings"><code>CompressionSettings</code></a> | <a href="./CompressionCodec.html"><code>CompressionCodec</code></a></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>BatchCodec</code></p><hr><h3 id="uncompressed" tabindex="-1">uncompressed() <a class="header-anchor" href="#uncompressed" aria-label="Permalink to “uncompressed()”">​</a></h3><blockquote><p><code>static</code> <strong>uncompressed</strong>(): <code>BatchCodec</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5129bc5166f8a781bd3f928e24b687744cdbd8c9/packages/protocol/src/BatchCodec.ts#L40" target="_blank" rel="noreferrer">protocol/src/BatchCodec.ts:40</a></p><p>The pre-negotiation form, carrying no algorithm byte. Only <code>RequestNetworkSettings</code> and <code>NetworkSettings</code> itself travel this way.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>BatchCodec</code></p>`,109)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};